from typing import Any

from pydantic import BaseModel, Field

from customer_service.schemas.enums import MessageType


class ChatMessageRequest(BaseModel):
    message_id: str = Field(
        title="Message ID",
        description=(
            "Generated by the frontend to prevent duplicate submissions on retries."
        ),
    )
    type: MessageType = Field(
        title="Message type",
        description="Message type: text or a message card.",
    )
    content: dict[str, Any] = Field(
        title="Message content",
        description=(
            "Message payload: plain text for text messages, structured data for "
            "message cards."
        ),
    )
